def table(headers,rows,caption=''):
    return '<div class="table-wrap"><table>'+ (f'<caption>{e(caption)}</caption>' if caption else '')+'<thead><tr>'+''.join(f'<th scope="col">{e(h)}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def resources(m,base='../'):
    r=''
    for x in m['evidence']:
        read=x.get('read')
        links=(f'<a href="{base}evidence/{read}">Read analysis →</a>' if read else '')+f'<a href="{base}evidence/{e(x["file"])}" download>Download {e(x["format"])} ↓</a>'
        r+=f'<div class="resource"><span class="file-icon" aria-hidden="true">{e(x["format"])}</span><div class="resource-copy"><h3>{e(x["title"])}</h3>{links}</div></div>'
    for x in m.get('textEvidence',[]):
        r+=f'<div class="resource"><span class="file-icon" aria-hidden="true">MEMO</span><div class="resource-copy"><h3>{e(x["title"])}</h3><a href="{base}evidence/{e(x["file"])}">Read submitted response →</a></div></div>'
    return r

